function parseFont(input) {
  switch (input) {
    case "_symbol": return "Symbol";
    case "_monospace": return "Monospace";
    case "_normal": return "Normal";
    case "_times": return "Times";
    case "_signature": return "Signature";
    default: return "Unknown";
  }
}


function registerBase64Font(fontName, base64Data) {
  const style = document.createElement("style");
  style.innerHTML = `
    @font-face {
      font-family: "${fontName}";
      src: url("data:font/ttf;base64,${base64Data}") format("truetype");
      font-weight: 400;
      font-style: normal;
    }
  `;
  document.head.appendChild(style);
}